// src/sdk/core.ts
// The shared core: identity, the event bus, and transport. Non-negotiable as a
// shared piece because events and decisions must be keyed to the same visitor
// id and one socket serves both directions. Extracted from the demo storefront:
// the socket URL, the welcome frame, the reconnect delay, the action envelope
// and the POST-versus-push dedupe are its behavior, verbatim.

import { currentSessionId, DEFAULT_VISITOR_KEY, entrySignals, writeVisitorId, rotateBrowsingSession } from './identity';
import { toWire } from './wire';
import type {
  ActionEnvelope, ClientConfig, CoreEvents, DecisionSet, EngineUpdate, EntrySignals, Host, Paths,
  SdkEventType, SocketLike, SocketStatus,
} from './types';

export const DEFAULT_PATHS: Paths = {
  identitySession: '/v1/{tenant}/identity/session',
  action: '/realtime/action',
  ws: '/realtime/ws',
  reflex: '/realtime/reflex',
  snapshot: '/v1/{tenant}/decisions/snapshot',
  identityLink: '/v1/{tenant}/identity/link',
  identityDetach: '/v1/{tenant}/identity/detach',
};

export interface ResolvedConfig {
  tenant: string;
  brand?: string;
  endpoint: string;
  sdkKey?: string;
  source: string;
  surface?: string;
  listenOnly: boolean;
  heartbeatMs: number;
  reconnectMs: number;
  hydrateTimeoutMs: number;
  visitorIdKey: string;
  paths: Paths;
}

export function resolveConfig(c: ClientConfig, host: Host): ResolvedConfig {
  const origin = host.location ? `${host.location.protocol}//${host.location.host}` : '';
  return {
    tenant: c.tenant,
    ...(c.brand ? { brand: c.brand } : {}),
    endpoint: (c.endpoint ?? origin).replace(/\/+$/, ''),
    ...(c.sdkKey ? { sdkKey: c.sdkKey } : {}),
    source: c.source ?? 'sdk',
    ...(c.surface ? { surface: c.surface } : {}),
    listenOnly: Boolean(c.listenOnly),
    heartbeatMs: c.heartbeatMs ?? 25_000,
    reconnectMs: c.reconnectMs ?? 3_000,
    hydrateTimeoutMs: c.hydrateTimeoutMs ?? 1_500,
    visitorIdKey: c.visitorIdKey ?? DEFAULT_VISITOR_KEY,
    paths: { ...DEFAULT_PATHS, ...(c.paths ?? {}) },
  };
}

export interface SendOptions {
  /** Fire-and-forget through the beacon API, for page-hide moments. */
  beacon?: boolean;
  keepalive?: boolean;
}

export interface Core {
  readonly generation: number;
  ready(transition?: boolean): Promise<boolean>;
  beginTransition(): number;
  finishTransition(generation: number): void;
  forgetSession(generation: number): void;
  isCurrent(generation: number): boolean;
  adoptSession(session: unknown, generation: number, reason: 'identified' | 'logout'): boolean;
  readonly config: ResolvedConfig;
  readonly host: Host;
  readonly visitorId: string;
  readonly anonId: string;
  readonly sessionId: string;
  readonly profileSessionId: string;
  readonly entry: EntrySignals;
  readonly socketStatus: SocketStatus;
  on<K extends keyof CoreEvents>(event: K, fn: CoreEvents[K]): () => void;
  emit<K extends keyof CoreEvents>(event: K, ...args: Parameters<CoreEvents[K]>): void;
  /** The envelope POST /realtime/action validates, for this event. Pure. */
  envelope(type: SdkEventType, data?: Record<string, unknown>): ActionEnvelope;
  send(type: SdkEventType, data?: Record<string, unknown>, opts?: SendOptions): Promise<EngineUpdate | null>;
  url(path: string, query?: Record<string, string | undefined>): string;
  headers(extra?: Record<string, string>): Record<string, string>;
  getJson(path: string, query?: Record<string, string | undefined>): Promise<unknown | null>;
  /** POST JSON with the site key and credentials; never throws. */
  postJson(path: string, body: unknown): Promise<{ ok: boolean; status: number; json: unknown }>;
  /** CW25: the browser now carries this id. Writes both stores, announces the change, reconnects the socket if it was open. */
  setVisitorId(id: string, reason: 'identified' | 'logout'): void;
  connect(): void;
  disconnect(): void;
  /** Apply an engine update from either door, once. */
  applyIncoming(update: EngineUpdate, fromPush: boolean, rttMs: number | null): void;
}

export function createCore(config: ClientConfig, host: Host): Core {
  const cfg = resolveConfig(config, host);
  let visitorId = '', sessionId = '', anonId = '';
  let generation = 0;
  let transitioning = false;
  let capability = '';
  let expiresAt = 0;
  let bootstrapping: Promise<boolean> | null = null;
  const capabilityKey = `opt_shopper_session:${encodeURIComponent(cfg.endpoint)}:${encodeURIComponent(cfg.tenant)}`;
  const refusalKey = `opt_shopper_refusal:${encodeURIComponent(cfg.endpoint)}:${encodeURIComponent(cfg.tenant)}`;
  let recovery: { tracking?: false; personalization?: false } = {};
  try {
    const saved = host.storage.get(refusalKey);
    if (saved) {
      const value = JSON.parse(saved);
      recovery = { ...(value?.tracking === false ? { tracking: false as const } : {}), ...(value?.personalization === false ? { personalization: false as const } : {}) };
      if (!Object.keys(recovery).length) recovery = { tracking: false, personalization: false };
    }
  } catch { recovery = { tracking: false, personalization: false }; }
  function rememberUnknownConsent(): void {
    recovery = { tracking: false, personalization: false };
    try { host.storage.set(refusalKey, JSON.stringify(recovery)); } catch { /* in-memory refusal still holds */ }
  }
  const session = () => currentSessionId(host);
  const entry = entrySignals(host);

  const listeners = new Map<string, Set<(...args: unknown[]) => void>>();
  function on<K extends keyof CoreEvents>(event: K, fn: CoreEvents[K]): () => void {
    const set = listeners.get(event) ?? new Set();
    set.add(fn as (...args: unknown[]) => void);
    listeners.set(event, set);
    return () => { set.delete(fn as (...args: unknown[]) => void); };
  }
  function emit<K extends keyof CoreEvents>(event: K, ...args: Parameters<CoreEvents[K]>): void {
    const g = generation;
    for (const fn of listeners.get(event) ?? []) { if (generation !== g) break; try { fn(...args); } catch { /* a listener must never break the page */ } }
  }

  // A shopper's own action returns the update in the POST response AND echoes
  // it over the socket. Apply once: both carry the same server timestamp.
  let lastAppliedTs: number | undefined;
  function applyIncoming(update: EngineUpdate, fromPush: boolean, rttMs: number | null): void {
    if (typeof update.timestamp === 'number') {
      if (fromPush && update.timestamp === lastAppliedTs) return;
      lastAppliedTs = update.timestamp;
    }
    emit('update', update, { fromPush, rttMs });
  }

  function url(path: string, query?: Record<string, string | undefined>): string {
    const base = `${cfg.endpoint}${path.replace('{tenant}', encodeURIComponent(cfg.tenant))}`;
    const parts = Object.entries(query ?? {}).filter(([, v]) => v !== undefined && v !== '')
      .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`);
    return parts.length ? `${base}?${parts.join('&')}` : base;
  }
  function headers(extra: Record<string, string> = {}): Record<string, string> {
    return { ...(cfg.sdkKey ? { 'X-SDK-Key': cfg.sdkKey } : {}), 'X-Tenant': cfg.tenant, ...(capability ? { 'X-Shopper-Session': capability } : {}), ...extra };
  }

  function isCurrent(g: number): boolean { return g === generation && !!capability && expiresAt * 1000 > host.now(); }
  function beginTransition(): number {
    const g = ++generation;
    transitioning = true;
    bootstrapping = null;
    lastAppliedTs = undefined;
    const reconnect = wanted;
    disconnect();
    if (g !== generation) return g;
    wanted = reconnect;
    emit('generation', g);
    return g;
  }
  function finishTransition(g: number): void {
    if (g !== generation) return;
    transitioning = false;
    if (wanted) connect();
  }
  function forgetSession(g: number): void {
    if (g !== generation) return;
    rememberUnknownConsent();
    capability = ''; expiresAt = 0; visitorId = ''; sessionId = ''; anonId = '';
    try { host.storage.set(capabilityKey, ''); } catch { /* storage unavailable */ }
    writeVisitorId(host, cfg.visitorIdKey, '');
    rotateBrowsingSession(host);
  }
  function adoptSession(value: unknown, g: number, reason: 'identified' | 'logout'): boolean {
    const v = value as { tenant?: unknown; subject?: unknown; sessionId?: unknown; capability?: unknown; kind?: unknown; exp?: unknown; iat?: unknown; consent?: { tracking?: unknown; personalization?: unknown } } | null;
    if (g !== generation || !v || v.tenant !== cfg.tenant || typeof v.subject !== 'string' || !v.subject
      || typeof v.sessionId !== 'string' || !v.sessionId || typeof v.capability !== 'string' || !/^ss1\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/.test(v.capability)
      || (v.kind !== 'anonymous' && v.kind !== 'recognized') || typeof v.exp !== 'number' || !Number.isSafeInteger(v.exp)
      || typeof v.iat !== 'number' || !Number.isSafeInteger(v.iat) || v.iat > host.now() / 1000 || v.exp * 1000 <= host.now() || v.exp - v.iat > 86400 || v.exp <= v.iat) return false;
    // A recovery response must acknowledge every restriction before activity resumes.
    if ((recovery.tracking === false && v.consent?.tracking !== false)
      || (recovery.personalization === false && v.consent?.personalization !== false)) return false;
    const previous = visitorId;
    if (previous && previous !== v.subject) rotateBrowsingSession(host);
    visitorId = v.subject; sessionId = v.sessionId; capability = v.capability; expiresAt = v.exp;
    anonId = v.kind === 'anonymous' ? v.subject : '';
    const retained = { ...recovery, ...(v.consent?.tracking === false ? { tracking: false } : {}), ...(v.consent?.personalization === false ? { personalization: false } : {}) };
    if (Object.keys(retained).length) try { host.storage.set(refusalKey, JSON.stringify(retained)); } catch { /* current memory still has acknowledged consent */ }
    try { host.storage.set(capabilityKey, capability); } catch { /* storage unavailable */ }
    recovery = {};
    let anchored = false;
    try {
      // Browser storage wrappers may swallow quota errors: verify the new anchor first.
      anchored = host.storage.get(capabilityKey) === capability;
      if (anchored) host.storage.set(refusalKey, '');
    } catch { /* a retained marker can only restrict a later recovery */ }
    if (!anchored) try {
      host.storage.set(refusalKey, JSON.stringify(Object.keys(retained).length ? retained : { tracking: false, personalization: false }));
    } catch { /* all client persistence may be unavailable; in-memory identity remains current */ }
    writeVisitorId(host, cfg.visitorIdKey, visitorId);
    emit('identity', { visitorId, previous, reason });
    if (g !== generation) return false;
    if (wanted && !transitioning) connect();
    return true;
  }
  function ready(transition = false): Promise<boolean> {
    if (transitioning && !transition) return Promise.resolve(false);
    if (isCurrent(generation)) return Promise.resolve(true);
    if (bootstrapping) return bootstrapping;
    if (capability) {
      const g = beginTransition();
      if (g !== generation) return Promise.resolve(false);
      rememberUnknownConsent();
      transitioning = false; capability = ''; expiresAt = 0; visitorId = ''; sessionId = '';
    }
    const g = generation;
    let persisted = '';
    try { persisted = host.storage.get(capabilityKey) ?? ''; } catch { /* storage unavailable */ }
    // A saved grant may be the OLD account when replacement persistence failed.
    if (Object.keys(recovery).length) persisted = '';
    const operation = (async () => {
      try {
        const request = () => host.fetch(url(cfg.paths.identitySession), { method: 'POST', credentials: 'include', headers: { ...headers({ 'Content-Type': 'application/json' }), ...(persisted ? { 'X-Shopper-Session': persisted } : {}) }, body: JSON.stringify(Object.keys(recovery).length ? { consent: recovery } : {}) });
        let res = await request();
        if (res.status === 401 && persisted && g === generation) {
          rememberUnknownConsent();
          persisted = '';
          try { host.storage.set(capabilityKey, ''); } catch { /* storage unavailable */ }
          res = await request();
        }
        const body = await res.json() as { ok?: unknown; session?: unknown } | null;
        if (g !== generation) return false;
        if (!res.ok || body?.ok !== true) {
          if (res.status === 401) try { host.storage.set(capabilityKey, ''); } catch { /* storage unavailable */ }
          return false;
        }
        return adoptSession(body.session, g, 'logout');
      } catch { return false; }
    })();
    bootstrapping = operation;
    void operation.finally(() => { if (bootstrapping === operation) bootstrapping = null; });
    return operation;
  }

  function envelope(type: SdkEventType, data: Record<string, unknown> = {}): ActionEnvelope {
    const w = toWire(type, data);
    return {
      type: w.type,
      userId: visitorId,
      anonymousId: anonId,
      sessionId,
      browsingSessionId: session(),
      data: w.data,
      source: cfg.source,
      ...(cfg.surface ? { surface: cfg.surface } : {}),
      entry,
      timestamp: host.now(),
    };
  }

  async function send(type: SdkEventType, data: Record<string, unknown> = {}, opts: SendOptions = {}): Promise<EngineUpdate | null> {
    const pending = ready();
    const g = generation;
    if (!await pending || !isCurrent(g)) return null;
    const env = envelope(type, data);
    const body = JSON.stringify(env);
    const target = url(cfg.paths.action);
    const t0 = host.now();
    try {
      const res = await host.fetch(target, {
        method: 'POST', headers: headers({ 'Content-Type': 'application/json' }), credentials: 'include', body,
        ...(opts.keepalive || opts.beacon ? { keepalive: true } : {}),
      });
      const json = (await res.json()) as { update?: { data?: EngineUpdate }; odp?: unknown } | null;
      if (!res.ok || !isCurrent(g)) return null;
      emit('sent', env, { via: 'fetch' });
      if (!isCurrent(g)) return null;
      if (json?.odp) emit('receipt', json.odp, { via: 'fetch' });
      if (!isCurrent(g)) return null;
      const update = json?.update?.data ?? null;
      if (update) applyIncoming(update, false, host.now() - t0);
      return isCurrent(g) ? update : null;
    } catch {
      return null;
    }
  }

  async function getJson(path: string, query?: Record<string, string | undefined>): Promise<unknown | null> {
    const pending = ready();
    const g = generation;
    if (!await pending || !isCurrent(g)) return null;
    try {
      const res = await host.fetch(url(path, query), { method: 'GET', headers: headers(), credentials: 'include' });
      const json = await res.json();
      return res.ok && isCurrent(g) ? json : null;
    } catch {
      return null;
    }
  }

  async function postJson(path: string, body: unknown): Promise<{ ok: boolean; status: number; json: unknown }> {
    const g = generation;
    const identityRequest = path === cfg.paths.identityLink || path === cfg.paths.identityDetach;
    if (!await ready(identityRequest) || !isCurrent(g)) return { ok: false, status: 0, json: null };
    try {
      const res = await host.fetch(url(path), { method: 'POST', headers: headers({ 'Content-Type': 'application/json' }), credentials: 'include', body: JSON.stringify(body) });
      let json: unknown = null;
      try { json = await res.json(); } catch { json = null; }
      return isCurrent(g) ? { ok: res.ok, status: res.status, json } : { ok: false, status: 0, json: null };
    } catch {
      return { ok: false, status: 0, json: null };
    }
  }

  function setVisitorId(id: string, reason: 'identified' | 'logout'): void {
    const previous = visitorId;
    if (!id) return;
    const g = beginTransition();
    if (g !== generation) return;
    rememberUnknownConsent();
    capability = ''; expiresAt = 0; sessionId = ''; anonId = '';
    rotateBrowsingSession(host);
    try { host.storage.set(capabilityKey, ''); } catch { /* storage unavailable */ }
    visitorId = id;
    writeVisitorId(host, cfg.visitorIdKey, id);
    emit('identity', { visitorId: id, previous, reason });
    finishTransition(g);
    // Pushes go to the object named by the id: a socket still open under the old one hears nothing.
    if (wanted) connect();
  }

  // ── The socket ──────────────────────────────────────────────────────────────
  let socket: SocketLike | null = null;
  let status: SocketStatus = host.openSocket ? 'closed' : 'unavailable';
  let wanted = false;
  let heartbeat: unknown = null;
  let reconnectTimer: unknown = null;
  let socketGeneration = 0;

  function setStatus(s: SocketStatus): void { status = s; emit('socket', s); }

  function socketUrl(): string | null {
    if (!cfg.endpoint) return null;
    const base = cfg.endpoint.replace(/^http(s?):/, (_m, secure: string) => `ws${secure}:`);
    const q = new URLSearchParams({ userId: visitorId, sessionId, tenant: cfg.tenant, ...(cfg.sdkKey ? { sdkKey: cfg.sdkKey } : {}) });
    return `${base}${cfg.paths.ws}?${q.toString()}`;
  }

  function handleFrame(raw: unknown): void {
    const g = generation;
    let msg: { type?: string; data?: Record<string, unknown>; [k: string]: unknown };
    try { msg = typeof raw === 'string' ? JSON.parse(raw) : (raw as typeof msg); } catch { return; }
    if (!msg || typeof msg !== 'object') return;
    const data = (msg.data ?? {}) as Record<string, unknown>;
    switch (msg.type) {
      case 'connected': setStatus('connected'); return;
      case 'heartbeat_response': return;
      case 'odp_receipt': emit('receipt', data, { via: 'push' }); return;
      case 'content_decisions': emit('decisions', msg as unknown as DecisionSet); return;
      default: break;
    }
    if (msg.type === 'audience_published' || data.audienceWentLive) emit('audience', data.audienceWentLive ?? msg.audienceWentLive ?? data);
    if (!isCurrent(g)) return;
    if (msg.type === 'personalization_update' || msg.type === 'segment_update' || data.segments) {
      const ms = typeof data.decisionMs === 'number' ? data.decisionMs : null;
      applyIncoming(data as EngineUpdate, true, ms);
    }
  }

  function stopHeartbeat(): void { if (heartbeat !== null) { host.clearInterval(heartbeat); heartbeat = null; } }

  function connect(): void {
    wanted = true;
    const g = generation, sg = ++socketGeneration;
    void ready().then(ok => {
      if (ok && wanted && isCurrent(g) && sg === socketGeneration) openSocket(g, sg);
    });
  }
  function openSocket(g: number, sg: number): void {
    if (!host.openSocket) { setStatus('unavailable'); return; }
    const target = socketUrl();
    if (!target) { setStatus('unavailable'); return; }
    if (reconnectTimer !== null) { host.clearTimeout(reconnectTimer); reconnectTimer = null; }
    setStatus('connecting');
    if (g !== generation || sg !== socketGeneration || !wanted || transitioning) return;
    try { socket = host.openSocket(target, ['shopper-session-v1', capability]); } catch { setStatus('error'); return; }
    const s = socket;
    const current = () => sg === socketGeneration && isCurrent(g);
    s.onopen = () => {
      if (!current()) { s.close(); return; }
      setStatus('connected');
      stopHeartbeat();
      heartbeat = host.setInterval(() => {
        if (!current()) { s.close(); return; }
        if (s.readyState === 1) { try { s.send(JSON.stringify({ type: 'heartbeat' })); } catch { /* dying socket */ } }
      }, cfg.heartbeatMs);
    };
    s.onmessage = (ev) => { if (current()) handleFrame(ev.data); };
    s.onerror = () => { if (current()) setStatus('error'); };
    s.onclose = () => {
      if (!current()) return;
      stopHeartbeat();
      if (!wanted) { setStatus('closed'); return; }
      setStatus('reconnecting');
      reconnectTimer = host.setTimeout(() => { reconnectTimer = null; if (wanted) connect(); }, cfg.reconnectMs);
    };
  }

  function disconnect(): void {
    socketGeneration++;
    wanted = false;
    stopHeartbeat();
    if (reconnectTimer !== null) { host.clearTimeout(reconnectTimer); reconnectTimer = null; }
    try { socket?.close(); } catch { /* ignore */ }
    socket = null;
    setStatus('closed');
  }

  return {
    config: cfg, host, entry,
    get anonId() { return anonId; },
    get generation() { return generation; },
    ready, beginTransition, finishTransition, forgetSession, isCurrent, adoptSession,
    get visitorId() { return visitorId; },
    get sessionId() { return session(); },
    get profileSessionId() { return sessionId; },
    get socketStatus() { return status; },
    on, emit, envelope, send, url, headers, getJson, postJson, setVisitorId, connect, disconnect, applyIncoming,
  };
}

// src/sdk/emit.ts
// The emit module: the four capture paths, used together. Explicit API for
// commerce (the conversion event is non-negotiable for outcome learning),
// declarative data-attributes for slot-level capture, a dataLayer adapter for
// sites that already have a tag layer, and the automatic path, which lives on
// the listen module because the SDK knows what it delivered.

import type { Core } from './core';
import type { Listen } from './listen';
import type { DomLike, ElementLike, EngineUpdate, SdkEventType } from './types';
import { WIRE } from './wire';

export interface PurchaseInput {
  orderId: string;
  value: number;
  currency?: string;
  items?: Array<{ productId: string; quantity?: number; price?: number; [k: string]: unknown }>;
  [k: string]: unknown;
}

export type DataLayerMapper = (entry: Record<string, unknown>) => { type: SdkEventType; data: Record<string, unknown> } | null;
export type DataLayerMapping = Record<string, DataLayerMapper>;

export interface DeclarativeOptions { dom?: DomLike; dwellMinMs?: number }
export interface DataLayerOptions { layer?: unknown[]; mapping?: DataLayerMapping; replay?: boolean }

export interface Emit {
  track(type: SdkEventType, data?: Record<string, unknown>): Promise<EngineUpdate | null>;
  pageView(data?: Record<string, unknown>): Promise<EngineUpdate | null>;
  productView(productId: string, attrs?: Record<string, unknown>): Promise<EngineUpdate | null>;
  addToCart(productId: string, attrs?: Record<string, unknown>): Promise<EngineUpdate | null>;
  wishlistAdd(productId: string, attrs?: Record<string, unknown>): Promise<EngineUpdate | null>;
  /** The conversion event. Sent with keepalive so a navigation away does not lose it. */
  purchase(input: PurchaseInput): Promise<EngineUpdate | null>;
  contentImpression(contentId: string, slot: string, attrs?: Record<string, unknown>): Promise<EngineUpdate | null>;
  contentClick(contentId: string, slot: string, attrs?: Record<string, unknown>): Promise<EngineUpdate | null>;
  contentDwell(contentId: string, slot: string, ms: number, attrs?: Record<string, unknown>): Promise<EngineUpdate | null>;
  videoComplete(contentId: string, slot: string, attrs?: Record<string, unknown>): Promise<EngineUpdate | null>;
  custom(name: string, data?: Record<string, unknown>): Promise<EngineUpdate | null>;
  /** Scan `[data-op-content]` and `[data-op-track]` elements. Returns a detach function. */
  declarative(opts?: DeclarativeOptions): () => void;
  /** Wrap a dataLayer's push. Returns a detach function that restores it. */
  dataLayer(opts?: DataLayerOptions): () => void;
  rendered: Listen['rendered'];
}

const first = (v: unknown): Record<string, unknown> => (Array.isArray(v) && v[0] && typeof v[0] === 'object' ? (v[0] as Record<string, unknown>) : {});
const eco = (e: Record<string, unknown>): Record<string, unknown> => (e.ecommerce && typeof e.ecommerce === 'object' ? (e.ecommerce as Record<string, unknown>) : e);

function ga4Item(e: Record<string, unknown>): Record<string, unknown> {
  const it = first(eco(e).items);
  return {
    productId: String(it.item_id ?? it.id ?? ''),
    ...(it.item_name !== undefined ? { name: it.item_name } : {}),
    ...(it.price !== undefined ? { price: it.price } : {}),
    ...(it.item_category !== undefined ? { category: it.item_category } : {}),
    ...(it.item_brand !== undefined ? { brand: it.item_brand } : {}),
    ...(it.item_variant !== undefined ? { variant: it.item_variant } : {}),
  };
}

/** GA4-style events, the shape most tag layers already produce. Override per site. */
export const GA4_MAPPING: DataLayerMapping = {
  page_view: (e) => ({ type: 'page_view', data: { path: e.page_location ?? e.page_path ?? '' } }),
  view_item: (e) => { const d = ga4Item(e); return d.productId ? { type: 'product_view', data: d } : null; },
  add_to_cart: (e) => { const d = ga4Item(e); return d.productId ? { type: 'add_to_cart', data: d } : null; },
  add_to_wishlist: (e) => { const d = ga4Item(e); return d.productId ? { type: 'wishlist_add', data: d } : null; },
  purchase: (e) => {
    const x = eco(e);
    const items = Array.isArray(x.items) ? (x.items as Array<Record<string, unknown>>).map((it) => ({
      productId: String(it.item_id ?? it.id ?? ''), quantity: it.quantity ?? 1, ...(it.price !== undefined ? { price: it.price } : {}),
    })) : [];
    return { type: 'purchase', data: { orderId: String(x.transaction_id ?? ''), value: Number(x.value ?? 0), currency: x.currency ?? 'USD', items } };
  },
};

export function createEmit(core: Core, listen: Listen): Emit {
  const host = core.host;
  const track = (type: SdkEventType, data: Record<string, unknown> = {}) => core.send(type, data);
  const withItem = (type: SdkEventType) => (productId: string, attrs: Record<string, unknown> = {}) => track(type, { productId, ...attrs });
  const withContent = (type: SdkEventType) => (contentId: string, slot: string, attrs: Record<string, unknown> = {}) => track(type, { contentId, slot, ...attrs });

  function declarative(opts: DeclarativeOptions = {}): () => void {
    if (core.config.listenOnly) return () => {};
    const dom = opts.dom ?? host.dom;
    if (!dom) return () => {};
    const dwellMinMs = opts.dwellMinMs ?? 1_000;
    const offs: Array<() => void> = [];
    const seen = new Set<string>();

    for (const el of dom.querySelectorAll('[data-op-content]')) {
      const contentId = el.getAttribute('data-op-content') ?? '';
      const slot = el.getAttribute('data-op-slot') ?? 'unknown';
      if (!contentId) continue;
      const attrs = { contentId, slot, ...(el.getAttribute('data-op-type') ? { contentType: el.getAttribute('data-op-type') } : {}) };
      let shownAt: number | null = null;
      offs.push(dom.observe(el, (visible) => {
        if (visible) {
          if (shownAt === null) shownAt = host.now();
          const key = `${slot}:${contentId}`;
          if (!seen.has(key)) { seen.add(key); void track('content_impression', attrs); }
          return;
        }
        if (shownAt === null) return;
        const ms = host.now() - shownAt;
        shownAt = null;
        if (ms >= dwellMinMs) void track('content_dwell', { ...attrs, ms });
      }));
      el.addEventListener('click', () => { void track('content_click', attrs); });
    }

    for (const el of dom.querySelectorAll('[data-op-track]')) {
      const type = el.getAttribute('data-op-track') ?? '';
      if (!(type in WIRE)) continue;
      const label = el.getAttribute('data-op-label');
      const productId = el.getAttribute('data-op-product');
      el.addEventListener('click', () => {
        void track(type as SdkEventType, { ...(label ? { label } : {}), ...(productId ? { productId } : {}) });
      });
    }
    return () => { for (const off of offs) off(); };
  }

  function dataLayer(opts: DataLayerOptions = {}): () => void {
    const layer = opts.layer ?? host.dataLayer;
    if (!layer) return () => {};
    const mapping: DataLayerMapping = { ...GA4_MAPPING, ...(opts.mapping ?? {}) };
    const handle = (entry: unknown) => {
      if (!entry || typeof entry !== 'object') return;
      const e = entry as Record<string, unknown>;
      const name = typeof e.event === 'string' ? e.event : null;
      if (!name) return;
      const m = mapping[name];
      if (!m) return;
      let mapped: ReturnType<DataLayerMapper> = null;
      try { mapped = m(e); } catch { mapped = null; }
      if (mapped) void track(mapped.type, mapped.data);
    };
    if (opts.replay !== false) for (const entry of [...layer]) handle(entry);
    const original = layer.push;
    layer.push = function (this: unknown[], ...args: unknown[]) {
      const r = original.apply(layer, args);
      for (const a of args) handle(a);
      return r;
    };
    return () => { layer.push = original; };
  }

  return {
    track,
    pageView: (data = {}) => track('page_view', { path: host.location?.href ?? '', ...data }),
    productView: withItem('product_view'),
    addToCart: withItem('add_to_cart'),
    wishlistAdd: withItem('wishlist_add'),
    purchase: (input) => core.send('purchase', { ...input }, { keepalive: true }),
    contentImpression: withContent('content_impression'),
    contentClick: withContent('content_click'),
    contentDwell: (contentId, slot, ms, attrs = {}) => track('content_dwell', { contentId, slot, ms, ...attrs }),
    videoComplete: withContent('video_complete'),
    custom: (name, data = {}) => track('custom', { event: name, ...data }),
    declarative,
    dataLayer,
    rendered: (slot: string, contentId: string, el?: ElementLike) => listen.rendered(slot, contentId, el),
  };
}

// src/sdk/listen.ts
// The listen module: decisions in, defaults guaranteed. A page hydrates from the
// snapshot at first paint, subscribes per slot, and is told plainly when there
// is nothing — because the page never waits on us and never shows a hole.

import type { Core } from './core';
import type { ContentDecision, DecisionSet, ElementLike } from './types';

export interface HydrateOptions {
  page: string;
  /** The entry channel, if the page knows it; recorded on the decision's cell. */
  channel?: string;
}

export type SlotCallback = (decisions: ContentDecision[], set: DecisionSet) => void;
export type SetCallback = (set: DecisionSet | null) => void;

export interface Listen {
  /** Fetch the first-paint snapshot and apply it. Resolves null on absence or failure, never rejects. */
  hydrate(opts: HydrateOptions): Promise<DecisionSet | null>;
  /**
   * Called with the slot's decisions, in order, every time a set arrives —
   * with an empty array when the set has nothing for the slot, so a page can
   * revert to its default. Returns the unsubscribe function.
   */
  subscribe(slot: string, cb: SlotCallback): () => void;
  /** Called with each set as it arrives, and with null on graceful absence. */
  onDecisions(cb: SetCallback): () => void;
  /** Apply a set from any source (a socket frame, a server-rendered payload). */
  apply(set: DecisionSet): void;
  current(): DecisionSet | null;
  /**
   * Tell the SDK what was painted. The automatic capture path starts here: an
   * impression is sent once per slot and piece, and dwell is measured while the
   * element is on screen when one is given. Off in listen-only mode.
   */
  rendered(slot: string, contentId: string, el?: ElementLike): void;
}

export interface ListenOptions {
  /** Minimum on-screen time before a dwell event is worth sending. */
  dwellMinMs?: number;
}

export function createListen(core: Core, opts: ListenOptions = {}): Listen {
  const host = core.host;
  const dwellMinMs = opts.dwellMinMs ?? 1_000;
  const slotSubs = new Map<string, Set<SlotCallback>>();
  const setSubs = new Set<SetCallback>();
  const impressed = new Set<string>();
  let current: DecisionSet | null = null;

  function notifyAbsence(): void { for (const cb of setSubs) { try { cb(null); } catch { /* never break the page */ } } }

  function apply(set: DecisionSet): void {
    const generation = core.generation;
    current = set;
    impressed.clear();
    const bySlot = new Map<string, ContentDecision[]>();
    for (const d of set.decisions ?? []) { const list = bySlot.get(d.slot) ?? []; list.push(d); bySlot.set(d.slot, list); }
    for (const list of bySlot.values()) list.sort((a, b) => a.order - b.order);
    for (const [slot, subs] of slotSubs) {
      const list = bySlot.get(slot) ?? [];
      for (const cb of subs) { if (generation !== core.generation) return; try { cb(list, set); } catch { /* never break the page */ } }
    }
    for (const cb of setSubs) { if (generation !== core.generation) return; try { cb(set); } catch { /* never break the page */ } }
  }

  core.on('decisions', (set) => apply(set));
  core.on('generation', () => {
    const page = current?.page ?? '';
    current = null;
    impressed.clear();
    for (const subs of slotSubs.values()) for (const cb of subs) { try { cb([], { page, decisions: [] }); } catch { /* listener isolation */ } }
    notifyAbsence();
  });

  async function hydrate(o: HydrateOptions): Promise<DecisionSet | null> {
    const pending = core.ready();
    const generation = core.generation;
    let settled = false;
    let timedOut = false;
    const timer = host.setTimeout(() => { if (!settled && generation === core.generation) { timedOut = true; notifyAbsence(); } }, core.config.hydrateTimeoutMs);
    if (!await pending || !core.isCurrent(generation)) {
      settled = true; host.clearTimeout(timer);
      if (!timedOut && generation === core.generation) notifyAbsence();
      return null;
    }
    const json = (await core.getJson(core.config.paths.snapshot, {
      page: o.page, visitorId: core.visitorId, sessionId: core.profileSessionId, browsingSessionId: core.sessionId, brand: core.config.brand, channel: o.channel,
    })) as { ok?: boolean; page?: string; arm?: string; versions?: Record<string, number>; config_label?: string; decisions?: unknown; ts?: number } | null;
    settled = true;
    host.clearTimeout(timer);
    if (!core.isCurrent(generation)) return null;
    if (!json || json.ok !== true || !Array.isArray(json.decisions)) {
      if (!timedOut) notifyAbsence();
      return null;
    }
    const set: DecisionSet = {
      page: json.page ?? o.page,
      ...(json.arm ? { arm: json.arm } : {}),
      ...(json.versions ? { versions: json.versions } : {}),
      ...(json.config_label ? { config_label: json.config_label } : {}),
      ...(typeof json.ts === 'number' ? { ts: json.ts } : {}),
      decisions: json.decisions as ContentDecision[],
    };
    // A late snapshot after the timeout is still applied: absence first, then
    // the decision when it arrives. The page never waited.
    apply(set);
    return core.isCurrent(generation) ? set : null;
  }

  function subscribe(slot: string, cb: SlotCallback): () => void {
    const set = slotSubs.get(slot) ?? new Set<SlotCallback>();
    set.add(cb);
    slotSubs.set(slot, set);
    if (current) {
      const list = (current.decisions ?? []).filter((d) => d.slot === slot).sort((a, b) => a.order - b.order);
      try { cb(list, current); } catch { /* ignore */ }
    }
    return () => { set.delete(cb); };
  }

  function onDecisions(cb: SetCallback): () => void {
    setSubs.add(cb);
    return () => { setSubs.delete(cb); };
  }

  function rendered(slot: string, contentId: string, el?: ElementLike): void {
    if (core.config.listenOnly) return;
    const key = `${slot}:${contentId}`;
    const generation = core.generation;
    if (impressed.has(key)) return;
    impressed.add(key);
    const piece = (current?.decisions ?? []).find((d) => d.slot === slot && d.contentId === contentId);
    const data = { contentId, slot, ...(piece ? { customerContentId: piece.customerContentId, contentType: piece.type } : {}) };
    void core.send('content_impression', data);
    if (el && host.dom) {
      let shownAt: number | null = null;
      const off = host.dom.observe(el, (visible) => {
        if (generation !== core.generation) { off(); return; }
        if (visible) { if (shownAt === null) shownAt = host.now(); return; }
        if (shownAt === null) return;
        const ms = host.now() - shownAt;
        shownAt = null;
        if (ms >= dwellMinMs) void core.send('content_dwell', { ...data, ms });
        off();
      });
    }
  }

  return { hydrate, subscribe, onDecisions, apply, current: () => current, rendered };
}

// src/sdk/host.ts
// Two hosts. `browserHost` binds the real browser. `memoryHost` runs the same
// SDK with nothing behind it: tests, server-side rendering, and the shape a
// native port fills in. Everything DOM-shaped in the SDK is reached through
// these, and only here.

import type { DomLike, ElementLike, Host, SocketLike } from './types';
export { memoryHost } from './memoryHost';


function domOf(doc: Document, win: Window & typeof globalThis): DomLike {
  return {
    querySelectorAll: (sel) => Array.from(doc.querySelectorAll(sel)) as unknown as ArrayLike<ElementLike> & Iterable<ElementLike>,
    observe: (el, cb) => {
      if (typeof win.IntersectionObserver !== 'function') { cb(true); return () => {}; }
      const io = new win.IntersectionObserver((entries) => {
        for (const e of entries) cb(e.intersectionRatio >= 0.5);
      }, { threshold: [0, 0.5] });
      io.observe(el as unknown as Element);
      return () => io.disconnect();
    },
  };
}

export function browserHost(): Host {
  const win = globalThis as unknown as Window & typeof globalThis;
  const doc: Document | undefined = typeof document !== 'undefined' ? document : undefined;
  const loc = typeof location !== 'undefined' ? location : undefined;
  const nav = typeof navigator !== 'undefined' ? navigator : undefined;
  const cookieRe = (k: string) => new RegExp(`(?:^|;\\s*)${k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}=([^;]+)`);
  return {
    now: () => Date.now(),
    uuid: () => (win.crypto && typeof win.crypto.randomUUID === 'function')
      ? win.crypto.randomUUID()
      : `${Math.random().toString(36).slice(2)}${Date.now().toString(36)}`,
    storage: {
      get: (k) => { try { return win.localStorage.getItem(k); } catch { return null; } },
      set: (k, v) => { try { win.localStorage.setItem(k, v); } catch { /* blocked */ } },
    },
    cookie: {
      get: (k) => { try { return (doc?.cookie.match(cookieRe(k)) ?? [])[1] ?? null; } catch { return null; } },
      set: (k, v, maxAge) => { try { if (doc) doc.cookie = `${k}=${v}; Max-Age=${maxAge}; Path=/; SameSite=Lax`; } catch { /* blocked */ } },
    },
    location: loc ? { href: loc.href, host: loc.host, hostname: loc.hostname, protocol: loc.protocol, search: loc.search } : null,
    referrer: doc?.referrer ?? '',
    fetch: (url, init) => win.fetch(url, init as RequestInit),
    ...(nav && typeof nav.sendBeacon === 'function'
      ? { sendBeacon: (url: string, body: string) => { try { return nav.sendBeacon(url, new Blob([body], { type: 'application/json' })); } catch { return false; } } }
      : {}),
    ...(typeof win.WebSocket === 'function' ? { openSocket: (url: string, protocols?: string[]) => new win.WebSocket(url, protocols) as unknown as SocketLike } : {}),
    setTimeout: (fn, ms) => win.setTimeout(fn, ms),
    clearTimeout: (h) => win.clearTimeout(h as number),
    setInterval: (fn, ms) => win.setInterval(fn, ms),
    clearInterval: (h) => win.clearInterval(h as number),
    onPageHide: (fn) => {
      try { win.addEventListener('pagehide', fn); } catch { /* ignore */ }
      try { doc?.addEventListener('visibilitychange', () => { if (doc.visibilityState === 'hidden') fn(); }); } catch { /* ignore */ }
    },
    ...(doc ? { dom: domOf(doc, win) } : {}),
    ...(Array.isArray((win as unknown as { dataLayer?: unknown }).dataLayer)
      ? { dataLayer: (win as unknown as { dataLayer: unknown[] }).dataLayer } : {}),
  };
}

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { createCore } from './core';
import { testHost, syntheticSession } from './testHost';

describe('core', () => {
  beforeEach(() => { vi.useFakeTimers(); });
  afterEach(() => { vi.useRealTimers(); });

  it('W04.02 coalesces bootstrap, scopes persisted credentials and recovers invalid grants once without bypassing503', async () => {
    const f = testHost(); f.host.storage.set('opt_visitor_id', 'victim'); f.host.cookie.set('opt_session_id', 'victim', 100);
    const core = createCore({ tenant: 'meridian' }, f.host);
    await Promise.all([core.ready(), core.send('page_view'), core.getJson('/realtime/reflex')]);
    expect(f.calls.filter(c => c.url.endsWith('/identity/session'))).toHaveLength(1);
    expect(core.visitorId).not.toBe('victim'); expect(core.headers()['X-Tenant']).toBe('meridian');
    for (const call of f.calls.filter(c => !c.url.endsWith('/identity/session'))) {
      expect(call.init?.headers?.['X-Shopper-Session']).toMatch(/^ss1\./); expect(call.url).not.toContain('ss1.');
    }
    const other = createCore({ tenant: 'coach', endpoint: 'https://other.invalid' }, f.host); await other.ready();
    expect(f.calls.at(-1)!.init?.headers).not.toHaveProperty('X-Shopper-Session');
    for (const status of [401, 503]) {
      const r = testHost(); r.host.storage.set('opt_shopper_session:https%3A%2F%2Fshop.example:coach', 'bad-persisted');
      let calls = 0;
      r.host.fetch = async (_url, init) => { calls++;
        return init?.headers?.['X-Shopper-Session'] ? { ok: false, status, json: async () => ({ ok: false }) }
          : { ok: true, status: 200, json: async () => ({ ok: true, session: { ...syntheticSession(r.host.now()), consent: { tracking: false, personalization: false } } }) };
      };
      expect(await createCore({ tenant: 'coach' }, r.host).ready()).toBe(status === 401);
      expect(calls).toBe(status === 401 ? 2 : 1);
    }
  });

  it('W04.02 delayed bootstrap/action and old socket frames cannot survive an ABA transition', async () => {
    const f = testHost(); let release!: () => void;
    const hold = new Promise<void>(r => { release = r; });
    f.host.fetch = async () => { await hold; return { ok: true, status: 200, json: async () => ({ ok: true, session: syntheticSession(f.host.now()) }) }; };
    const core = createCore({ tenant: 'coach' }, f.host), pending = core.ready();
    core.setVisitorId('newer', 'logout'); release(); expect(await pending).toBe(false); expect(core.visitorId).toBe('newer');
    const r = testHost(), active = createCore({ tenant: 'coach' }, r.host); await active.ready(); active.connect(); await Promise.resolve();
    const old = r.sockets[0]!, updates: unknown[] = []; active.on('update', u => updates.push(u));
    let done!: () => void, entered!: () => void;
    const started = new Promise<void>(resolve => { entered = resolve; }); const delayed = new Promise<void>(resolve => { done = resolve; });
    r.host.fetch = async () => { entered(); await delayed; return { ok: true, status: 200, json: async () => ({ update: { data: { segments: ['PRIVATE'] } } }) }; };
    const action = active.send('page_view'); await started;
    const visitor = active.visitorId; active.disconnect(); active.setVisitorId('other', 'logout'); active.setVisitorId(visitor, 'logout');
    old.receive({ type: 'personalization_update', data: { segments: ['PRIVATE'] } }); done();
    expect(await action).toBeNull(); expect(updates).toEqual([]);
  });

  it('W05.01 retains scoped refusal recovery across missing acknowledgments and silently failed credential persistence', async () => {
    const f = testHost(), key = 'opt_shopper_refusal:https%3A%2F%2Fshop.example:coach';
    const core = createCore({ tenant: 'coach' }, f.host); await core.ready();
    const g = core.beginTransition(); core.forgetSession(g); core.finishTransition(g);
    const store = f.host.storage.set;
    f.host.storage.set = (key, value) => { if (!(key.startsWith('opt_shopper_session:') && value)) store(key, value); };
    const requests: any[] = []; let ack = false;
    f.host.fetch = async (_url, init) => {
      const body = JSON.parse(init?.body ?? '{}'); requests.push(body);
      return { ok: true, status: 200, json: async () => ({ ok: true, session: { ...syntheticSession(f.host.now(), undefined, init?.headers?.['X-Tenant']), ...(ack ? { consent: body.consent ?? { tracking: true, personalization: true } } : {}) } }) };
    };
    expect(await core.ready()).toBe(false); expect(f.host.storage.get(key)).toContain('false');
    ack = true; expect(await core.ready()).toBe(true); expect(f.host.storage.get(key)).toContain('false');
    expect(await createCore({ tenant: 'coach' }, f.host).ready()).toBe(true);
    expect(requests.slice(0, 3)).toEqual(Array(3).fill({ consent: { tracking: false, personalization: false } }));
    f.tick(3_601_000); expect(await core.ready()).toBe(true);
    expect(requests.at(-1)).toEqual({ consent: { tracking: false, personalization: false } });
    expect(await createCore({ tenant: 'meridian' }, f.host).ready()).toBe(true);
    expect(requests.at(-1)).toEqual({});
    for (const tracking of [false, true]) {
      const ordinary = testHost(), ordinaryCore = createCore({ tenant: 'coach' }, ordinary.host);
      await ordinaryCore.ready();
      const previous = syntheticSession(ordinary.host.now(), 'sh_' + 'a'.repeat(32));
      expect(ordinaryCore.adoptSession(previous, ordinaryCore.generation, 'identified')).toBe(true);
      const ordinaryStore = ordinary.host.storage.set;
      ordinary.host.storage.set = (key, value) => { if (!(key.startsWith('opt_shopper_session:') && value)) ordinaryStore(key, value); };
      const fresh = { ...syntheticSession(ordinary.host.now()), consent: { tracking, personalization: true } };
      expect(ordinaryCore.adoptSession(fresh, ordinaryCore.generation, 'logout')).toBe(true);
      expect(ordinaryCore.visitorId).toBe(fresh.subject);
      expect(ordinary.host.storage.get('opt_shopper_session:https%3A%2F%2Fshop.example:coach')).toBe(previous.capability);
      const expected = tracking ? { tracking: false, personalization: false } : { tracking: false };
      expect(ordinary.host.storage.get(key)).toBe(JSON.stringify(expected));
      const ordinaryRequests: any[] = [];
      ordinary.host.fetch = async (_url, init) => {
        ordinaryRequests.push(JSON.parse(init?.body ?? '{}'));
        expect(init?.headers).not.toHaveProperty('X-Shopper-Session');
        return { ok: true, status: 200, json: async () => ({ ok: true, session: { ...syntheticSession(ordinary.host.now()), consent: { tracking: false, personalization: expected.personalization !== false } } }) };
      };
      const reloaded = createCore({ tenant: 'coach' }, ordinary.host);
      expect(await reloaded.ready()).toBe(true); expect(reloaded.visitorId).not.toBe(previous.subject);
      expect(ordinaryRequests).toEqual([{ consent: expected }]);
    }
  });

  it('builds the envelope the storefront sends, field for field', async () => {
    const { host } = testHost();
    const core = createCore({ tenant: 'coach', source: 'coach-storefront', surface: 'coach' }, host);
    await core.ready();
    const env = core.envelope('product_view', { productId: 'SKU-1' });
    expect(Object.keys(env)).toEqual(['type', 'userId', 'anonymousId', 'sessionId', 'browsingSessionId', 'data', 'source', 'surface', 'entry', 'timestamp']);
    expect(env.userId).toMatch(/^vis-/);
    expect(env.anonymousId).toBe(env.userId);
    expect(env.sessionId).toBe(core.profileSessionId);
    expect(env.browsingSessionId).toBe(core.sessionId);
    expect(env.data).toEqual({ productId: 'SKU-1' });
    expect(env.entry).toEqual({ utmMedium: 'paid_social', utmSource: 'tiktok', referrer: 'https://www.tiktok.com/', siteHost: 'shop.example' });
    expect(env.timestamp).toBe(1_725_000_000_000);
    expect(Object.keys(createCore({ tenant: 'coach' }, host).envelope('page_view'))).not.toContain('surface');
  });

  it('POSTs to /realtime/action with credentials, applies the update, and reports the receipt', async () => {
    const { host, calls } = testHost({ responses: () => ({ success: true, update: { data: { timestamp: 7, segments: ['evening_affinity'] } }, odp: { receiptId: 'r1' } }) });
    const core = createCore({ tenant: 'coach', sdkKey: 'k-1' }, host);
    const updates: unknown[] = [], receipts: unknown[] = [], sent: unknown[] = [];
    core.on('update', (u, m) => updates.push([u, m])); core.on('receipt', (r) => receipts.push(r)); core.on('sent', (_e, m) => sent.push(m));
    const out = await core.send('add_to_cart', { productId: 'SKU-1' });
    expect(calls[1]?.url).toBe('https://shop.example/realtime/action');
    expect(calls[1]?.init).toMatchObject({ method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json', 'X-SDK-Key': 'k-1' } });
    expect(JSON.parse(calls[1]!.init!.body!)).toMatchObject({ type: 'add_to_cart', data: { productId: 'SKU-1' } });
    expect(out).toEqual({ timestamp: 7, segments: ['evening_affinity'] });
    expect(updates).toEqual([[{ timestamp: 7, segments: ['evening_affinity'] }, { fromPush: false, rttMs: 0 }]]);
    expect(receipts).toEqual([{ receiptId: 'r1' }]);
    expect(sent).toEqual([{ via: 'fetch' }]);
  });

  it('a failed POST resolves null and never throws', async () => {
    const { host } = testHost();
    host.fetch = async () => { throw new Error('offline'); };
    const core = createCore({ tenant: 'coach' }, host);
    await expect(core.send('page_view')).resolves.toBeNull();
  });

  it('uses authenticated keepalive fetch instead of a headerless beacon', async () => {
    const { host, calls, beacons } = testHost();
    const core = createCore({ tenant: 'coach' }, host);
    await core.send('purchase', { orderId: 'o1', value: 10 }, { beacon: true });
    expect(beacons).toHaveLength(0);
    expect(JSON.parse(calls[1]!.init!.body!)).toMatchObject({ type: 'purchase', data: { orderId: 'o1' } });
    expect(calls[1]!.init).toMatchObject({ keepalive: true, headers: { 'X-Shopper-Session': expect.stringMatching(/^ss1\./), 'X-Tenant': 'coach' } });
    expect(calls).toHaveLength(2);
  });

  it('opens the socket on the visitor id, heartbeats, dedupes the echo, reconnects on close', async () => {
    const { host, sockets } = testHost({ responses: () => ({ update: { data: { timestamp: 42, segments: ['a'] } } }) });
    const core = createCore({ tenant: 'coach', heartbeatMs: 1000, reconnectMs: 500 }, host);
    const status: string[] = []; core.on('socket', (s) => status.push(s));
    const updates: unknown[] = []; core.on('update', (u) => updates.push(u));
    await core.ready();
    core.connect();
    await Promise.resolve();
